		{"empty asset", []Balance{{Account: "aa-1", Asset: "", Balance: 10}}},
		{"negative balance", []Balance{{Account: "aa-1", Asset: "usdc", Balance: -1}}},
		{"duplicate pair", []Balance{
			{Account: "aa-1", Asset: "usdc", Balance: 10},
			{Account: "aa-1", Asset: "usdc", Balance: 20},
		}},
