			if !errors.Is(err, ErrInvalid) {
				t.Fatalf("Init = %v, want ErrInvalid", err)
			}
			if _, err := os.Stat(path); !os.IsNotExist(err) {
				t.Fatalf("ledger file created after invalid init")
			}
			if _, err := os.Stat(lockPath(path)); !os.IsNotExist(err) {
