	for g := 0; g < goroutines; g++ {
		wg.Add(1)
		go func(g int) {
			defer wg.Done()
			l, err := Open(path)
			if err != nil {
				t.Errorf("Open: %v", err)
				return
			}
			defer l.Close()
			results, err := l.Submit(Batch{FeeBps: 0, Intents: []Intent{
				intent(fmt.Sprintf("pay-%d", g), "aa-1", "pm-1", "usdc", 100, uint64(g+1), "pending"),
			}})
