content.content:
1	// Package payflow implements payment intent settlement and reconciliation.
2	package payflow
3	
4	import (
5		"encoding/json"
6		"errors"
7		"fmt"
8		"math"
9		"os"
10		"sync"
11		"syscall"
12	)
13	
14	// Per-item result statuses.
15	const (
16		StatusSettled      = "settled"
17		StatusDuplicate    = "duplicate"
18		StatusConflict     = "conflict"
19		StatusStateError   = "state_error"
20		StatusInsufficient = "insufficient"
21		StatusRejected     = "rejected"
22		StatusStorageError = "storage_error"
23	)
24	
25	// Ledger errors.
26	var (
27		ErrNotFound = errors.New("ledger not found")
28		ErrExists   = errors.New("ledger already exists")
29		ErrInvalid  = errors.New("invalid ledger data")
30	)
31	
32	// State is the persisted ledger state.
33	type State struct {
34		Version  int       `json:"version"`
35		Balances []Balance `json:"balances"`
36		Records  []Record  `json:"records"`
37	}
38	
39	// Balance is an account-asset balance.
40	type Balance struct {
41		Account string `json:"account"`
42		Asset   string `json:"asset"`
43		Balance int64  `json:"balance"`
44	}
45	
46	// Record is a settled payment, traceable to the original intent and fee.
47	type Record struct {
48		Intent  Intent `json:"intent"`
49		FeeBps  int    `json:"fee_bps"`
50		Charged int64  `json:"charged"`
51		Ref     string `json:"ref"`
52		Seq     int64  `json:"seq"`
53	}
54	
55	// Result is the per-item outcome, aligned with the input order.
56	type Result struct {
57		Intent  string `json:"intent"`
58		Status  string `json:"status"`
59		Charged int64  `json:"charged,omitempty"`
60		FeeBps  int    `json:"fee_bps,omitempty"`
61		Ref     string `json:"ref,omitempty"`
62		Reason  string `json:"reason,omitempty"`
63	}
64	
65	// Batch is a JSON payment batch carrying a fixed fee rate.
66	type Batch struct {
67		FeeBps  int      `json:"fee_bps"`
68		Intents []Intent `json:"intents"`
69	}
70	
71	// Ledger is an open local ledger. A Ledger is safe for concurrent use by
72	// multiple goroutines; the in-process mutex serializes them while the
73	// flock serializes separate opens of the same path.
74	type Ledger struct {
75		path string
76		lock *os.File
77		mu   sync.Mutex
78		st   State
79	}
80	
81	func lockPath(path string) string { return path + ".lock" }
82	
83	// Init creates a new ledger at path with the given balances.
84	// It validates everything before creating anything and refuses to
85	// overwrite an existing ledger.
86	func Init(path string, balances []Balance) error {
87		if err := validateBalances(balances); err != nil {
88			return err
89		}
90		f, err := os.OpenFile(lockPath(path), os.O_RDWR|os.O_CREATE, 0o600)
91		if err != nil {
92			return err
93		}
94		defer f.Close()
95		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX); err != nil {
96			return err
97		}
98		if _, err := os.Stat(path); err == nil {
99			return ErrExists
100		} else if !os.IsNotExist(err) {
101			return err
102		}
103		st := State{Version: 1, Balances: cloneBalances(balances), Records: []Record{}}
104		data, err := json.MarshalIndent(st, "", "  ")
105		if err != nil {
106			return err
107		}
108		return writeAtomic(path, data)
109	}
110	
111	// Open opens an existing ledger, taking an exclusive lock for its lifetime.
112	// A missing ledger or a corrupt one is reported, never silently reset.
113	func Open(path string) (*Ledger, error) {
114		f, err := os.OpenFile(lockPath(path), os.O_RDWR|os.O_CREATE, 0o600)
115		if err != nil {
116			return nil, err
117		}
118		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX); err != nil {
119			f.Close()
120			return nil, err
121		}
122		data, err := os.ReadFile(path)
123		if err != nil {
124			f.Close()
125			if os.IsNotExist(err) {
126				return nil, ErrNotFound
127			}
128			return nil, err
129		}
130		var st State
131		if err := json.Unmarshal(data, &st); err != nil {
132			f.Close()
133			return nil, fmt.Errorf("%w: %v", ErrInvalid, err)
134		}
135		if err := validateState(st); err != nil {
136			f.Close()
137			return nil, err
138		}
139		return &Ledger{path: path, lock: f, st: st}, nil
140	}
141	
142	// Close releases the ledger lock.
143	func (l *Ledger) Close() error {
144		if l.lock == nil {
145			return nil
146		}
147		err := syscall.Flock(int(l.lock.Fd()), syscall.LOCK_UN)
148		cerr := l.lock.Close()
149		l.lock = nil
150		if err != nil {
151			return err
152		}
153		return cerr
154	}
155	
156	// Submit applies a batch, returning one result per intent in input order.
157	// Each item is settled independently and saved atomically; a save failure
158	// preserves that item's pre-execution state while earlier items stand.
159	func (l *Ledger) Submit(batch Batch) ([]Result, error) {
160		l.mu.Lock()
161		defer l.mu.Unlock()
162		results := make([]Result, 0, len(batch.Intents))
163		for _, in := range batch.Intents {
164			results = append(results, l.process(in, batch.FeeBps))
165		}
166		return results, nil
167	}
168	
169	// Balances returns the current account-asset balances.
170	func (l *Ledger) Balances() []Balance {
171		l.mu.Lock()
172		defer l.mu.Unlock()
173		return cloneBalances(l.st.Balances)
174	}
175	
176	// Records returns settled records in settlement success order.
177	func (l *Ledger) Records() []Record {
178		l.mu.Lock()
179		defer l.mu.Unlock()
180		out := make([]Record, len(l.st.Records))
181		copy(out, l.st.Records)
182		return out
183	}
184	
185	func (l *Ledger) process(in Intent, feeBps int) Result {
186		// 1. Parameter validation.
187		if in.ID == "" || in.Account == "" || in.Asset == "" || in.Paymaster == "" {
188			return Result{Intent: in.ID, Status: StatusRejected, Reason: "empty required field"}
189		}
190		if in.Amount <= 0 {
191			return Result{Intent: in.ID, Status: StatusRejected, Reason: "amount must be a positive int64"}
192		}
193		if feeBps < 0 || feeBps > 10000 {
194			return Result{Intent: in.ID, Status: StatusRejected, Reason: "fee rate out of range [0,10000] bps"}
195		}
196		feeProduct, ok := mul64(in.Amount, int64(feeBps))
197		if !ok {
198			return Result{Intent: in.ID, Status: StatusRejected, Reason: "fee amount overflows int64"}
199		}
200		feeAmount := feeProduct / 10000
201		total, ok := add64(in.Amount, feeAmount)
202		if !ok {
203			return Result{Intent: in.ID, Status: StatusRejected, Reason: "deduction total overflows int64"}
204		}
205	
206		// 2. State check: non-pending is reported on its own.
207		if in.State != "pending" {
208			return Result{Intent: in.ID, Status: StatusStateError, Reason: "intent is not pending"}
209		}
210	
211		// 3. Dedup: a settled id with identical fields replays; otherwise conflict.
212		if rec, found := l.findRecord(in.ID); found {
213			if rec.matches(in, feeBps) {
214				return Result{
215					Intent:  in.ID,
216					Status:  StatusDuplicate,
217					Charged: rec.Charged,
218					FeeBps:  rec.FeeBps,
219					Ref:     rec.Ref,
220					Reason:  "duplicate of settled intent",
221				}
222			}
223			return Result{Intent: in.ID, Status: StatusConflict, Reason: "intent id conflicts with a settled payment"}
224		}
225	
226		// 4. Balance check: a missing account-asset is treated as insufficient.
227		idx := l.findBalance(in.Account, in.Asset)
228		if idx < 0 || l.st.Balances[idx].Balance < total {
229			return Result{Intent: in.ID, Status: StatusInsufficient, Reason: "insufficient balance for amount plus fee"}
230		}
231	
232		// 5. Settle: mutate in memory, then save; roll back on save failure.
233		l.st.Balances[idx].Balance -= total
234		rec := Record{
235			Intent:  in,
236			FeeBps:  feeBps,
237			Charged: total,
238			Ref:     "settle:" + in.ID,
239			Seq:     l.nextSeq(),
240		}
241		l.st.Records = append(l.st.Records, rec)
242		if err := l.save(); err != nil {
243			l.st.Balances[idx].Balance += total
244			l.st.Records = l.st.Records[:len(l.st.Records)-1]
245			return Result{Intent: in.ID, Status: StatusStorageError, Reason: err.Error()}
246		}
247		return Result{Intent: in.ID, Status: StatusSettled, Charged: total, FeeBps: feeBps, Ref: rec.Ref}
248	}
249	
250	func (l *Ledger) findRecord(id string) (Record, bool) {
251		for _, r := range l.st.Records {
252			if r.Intent.ID == id {
253				return r, true
254			}
255		}
256		return Record{}, false
257	}
258	
259	func (r Record) matches(in Intent, feeBps int) bool {
260		return r.FeeBps == feeBps &&
261			r.Intent.Account == in.Account &&
262			r.Intent.Paymaster == in.Paymaster &&
263			r.Intent.Asset == in.Asset &&
264			r.Intent.Amount == in.Amount &&
265			r.Intent.Nonce == in.Nonce
266	}
267	
268	func (l *Ledger) findBalance(account, asset string) int {
269		for i, b := range l.st.Balances {
270			if b.Account == account && b.Asset == asset {
271				return i
272			}
273		}
274		return -1
275	}
276	
277	func (l *Ledger) nextSeq() int64 {
278		var max int64
279		for _, r := range l.st.Records {
280			if r.Seq > max {
281				max = r.Seq
282			}
283		}
284		return max + 1
285	}
286	
287	func (l *Ledger) save() error {
288		data, err := json.MarshalIndent(l.st, "", "  ")
289		if err != nil {
290			return err
291		}
292		return writeAtomic(l.path, data)
293	}
294	
295	func validateBalances(balances []Balance) error {
296		seen := make(map[string]bool)
297		for _, b := range balances {
298			if b.Account == "" || b.Asset == "" {
299				return fmt.Errorf("%w: empty account or asset", ErrInvalid)
300			}
301			if b.Balance < 0 {
302				return fmt.Errorf("%w: negative balance for %s/%s", ErrInvalid, b.Account, b.Asset)
303			}
304			key := b.Account + "\x00" + b.Asset
305			if seen[key] {
306				return fmt.Errorf("%w: duplicate balance for %s/%s", ErrInvalid, b.Account, b.Asset)
307			}
308			seen[key] = true
309		}
310		return nil
311	}
312	
313	func validateState(st State) error {
314		if st.Version != 1 {
315			return fmt.Errorf("%w: unsupported version %d", ErrInvalid, st.Version)
316		}
317		if err := validateBalances(st.Balances); err != nil {
318			return err
319		}
320		seen := make(map[string]bool)
321		for _, r := range st.Records {
322			if r.Intent.ID == "" || r.Intent.Account == "" || r.Intent.Asset == "" || r.Intent.Paymaster == "" {
323				return fmt.Errorf("%w: record with empty required field", ErrInvalid)
324			}
325			if r.Intent.Amount <= 0 {
326				return fmt.Errorf("%w: record with non-positive amount", ErrInvalid)
327			}
328			if r.FeeBps < 0 || r.FeeBps > 10000 {
329				return fmt.Errorf("%w: record with invalid fee rate", ErrInvalid)
330			}
331			if r.Charged < 0 {
332				return fmt.Errorf("%w: record with negative charged amount", ErrInvalid)
333			}
334			if seen[r.Intent.ID] {
335				return fmt.Errorf("%w: duplicate settled id %q", ErrInvalid, r.Intent.ID)
336			}
337			seen[r.Intent.ID] = true
338		}
339		return nil
340	}
341	
342	func cloneBalances(in []Balance) []Balance {
343		out := make([]Balance, len(in))
344		copy(out, in)
345		return out
346	}
347	
348	// writeAtomic writes data to a temp file in the same directory, fsyncs it,
349	// and renames it over the target so a crash leaves either the old or the
350	// new complete state, never a partial one.
351	func writeAtomic(path string, data []byte) error {
352		dir := dirOf(path)
353		f, err := os.CreateTemp(dir, ".payflow-*")
354		if err != nil {
355			return err
356		}
357		tmp := f.Name()
358		keep := false
359		defer func() {
360			if !keep {
361				os.Remove(tmp)
362			}
363		}()
364		if _, err := f.Write(data); err != nil {
365			f.Close()
366			return err
367		}
368		if err := f.Sync(); err != nil {
369			f.Close()
370			return err
371		}
372		if err := f.Close(); err != nil {
373			return err
374		}
375		if err := os.Rename(tmp, path); err != nil {
376			return err
377		}
378		if d, err := os.Open(dir); err == nil {
379			_ = d.Sync()
380			_ = d.Close()
381		}
382		keep = true
383		return nil
384	}
385	
386	func dirOf(path string) string {
387		for i := len(path) - 1; i >= 0; i-- {
388			if path[i] == '/' {
389				if i == 0 {
390					return "/"
391				}
392				return path[:i]
393			}
394		}
395		return "."
396	}
397	
398	// mul64 multiplies two non-negative int64 values, reporting overflow.
399	func mul64(a, b int64) (int64, bool) {
400		if a == 0 || b == 0 {
401			return 0, true
402		}
403		c := a * b
404		if c/a != b {
405			return 0, false
406		}
407		return c, true
408	}
409	
410	// add64 adds two non-negative int64 values, reporting overflow.
411	func add64(a, b int64) (int64, bool) {
412		if b > 0 && a > math.MaxInt64-b {
413			return 0, false
414		}
415		return a + b, true
416	}
